        List<Instr> instructions = instrs(b, a, "1", a, c, "6");
        String settlementKey = key("sk");
        postJson("/api/settlements", settlementBody(
                key("ck"), key("rq"), settlementKey, windowId, instructions, versions(a, b, c)), 422);

